const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};try{saved=JSON.parse(localStorage.getItem('ctc-toolcraft-v1')||'{}')}catch(e){}
const state={completed:[],passed:[],notes:{},brief:{},lastLesson:null,...saved};
let lab={kind:'endmill',view:'3d',flutes:3,helix:30,core:52,rake:12,relief:8,feature:'edges',spin:false,exploded:false};
let world=null,activeCase=0,activeStep=0,cut={d:6,n:12000,z:3,fz:0.025,ae:25,ap:3,length:3};
const icons={lab:'M4 19 17 6M5 16l3 3M8 13l3 3M11 10l3 3M14 7l3 3M16 5l3-3 3 3-3 3',learn:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3ZM12 6v15',cutting:'M12 3v5M12 16v5M3 12h5M16 12h5M7 7l-3-3M17 17l3 3M7 17l-3 3M17 7l3-3M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',manufacture:'M3 21V10l6 3V7l6 4V3h6v18ZM6 17h2M11 17h2M17 16h1',diagnostics:'M10 3h4l1 6 5 3-2 4-6-2-5 5-3-3 5-5Z',ai:'M8 4h8v4h4v8h-4v4H8v-4H4V8h4ZM9 9h6v6H9',field:'M5 3h14v18H5ZM8 7h8M8 11h8M8 15h5',sources:'M4 4h6v16H4ZM14 4l5-1 3 16-5 1Z'};
const nav=[['learn','Learning path'],['lab','Geometry lab'],['cutting','Cutting lab'],['manufacture','Making the tool'],['diagnostics','Failure detective'],['ai','AI design studio'],['field','Shop-floor fieldbook'],['sources','Glossary & sources']];
$('#navigation').innerHTML=nav.map(([id,name])=>`<a class="nav-item" href="#${id}" data-route="${id}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[id]}"/></svg>${name}</a>`).join('');
function save(){try{localStorage.setItem('ctc-toolcraft-v1',JSON.stringify(state))}catch(e){toast('Storage unavailable. Export your learning record to keep it.')}updateProgress()}
function updateProgress(){$('#progress-fill').style.width=(state.completed.length/DATA.modules.length*100)+'%';$('#progress-text').textContent=`${state.completed.length} of ${DATA.modules.length} lessons completed`}
function toast(msg){const t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3500)}
function download(filename,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
$('#export-progress').onclick=()=>download('ctc-learning-record.json',JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2));
function heading(kicker,title,desc,right=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${right?`<span class="page-number">${right}</span>`:''}</div><div id="voice-learning-slot"></div>`}
function sourceLinks(list){return (list||[]).map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener">${escapeHTML(s.title)} ↗</a>`).join('')}
function range(id,label,min,max,step,value,unit=''){return `<div class="field"><div class="field-title"><label for="${id}">${label}</label><output id="${id}-out">${value}${unit}</output></div><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-unit="${unit}"></div>`}
let pendingLessonVoice = null;
function closeNavigation(restoreFocus=false){document.body.classList.remove('navigation-open');$('#mobile-menu-toggle').setAttribute('aria-expanded','false');$('#mobile-menu-toggle').setAttribute('aria-label','Open navigation');$('#mobile-menu-scrim').hidden=true;if(restoreFocus)$('#mobile-menu-toggle').focus()}
$('#mobile-menu-toggle').onclick=()=>{const open=!document.body.classList.contains('navigation-open');document.body.classList.toggle('navigation-open',open);$('#mobile-menu-toggle').setAttribute('aria-expanded',String(open));$('#mobile-menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#mobile-menu-scrim').hidden=!open;if(open)$('#navigation a').focus()};
$('#mobile-menu-scrim').onclick=()=>closeNavigation(true);
$('#navigation').addEventListener('click',e=>{if(e.target.closest('a'))closeNavigation(true)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('navigation-open'))closeNavigation(true);if(e.key==='Tab'&&document.body.classList.contains('navigation-open')){const controls=[...document.querySelectorAll('.rail a,.rail button')];const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function startLesson(id,mode){if(!DATA.modules.some(m=>m.id===id))return;pendingLessonVoice=mode||null;if(location.hash===`#lesson/${id}`){if(mode)window.AcademyVoice?.start(mode);pendingLessonVoice=null}else location.hash=`lesson/${id}`}
function route(){
 disposeWorld();closeNavigation();
 const requested=location.hash.slice(1)||'learn';
 const hash=requested.startsWith('lesson/')||nav.some(n=>n[0]===requested)?requested:'learn';
 const section=hash.startsWith('lesson/')?'learn':hash;
 document.body.dataset.page=section;
 $$('.nav-item').forEach(e=>{e.classList.toggle('active',e.dataset.route===section);if(e.dataset.route===section)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current')});
 $('#breadcrumb').textContent=hash.startsWith('lesson/')?'Learning path / Your lesson':(nav.find(n=>n[0]===section)?.[1]||'Learning path');
 const actions={lab:renderLab,learn:renderLearn,cutting:renderCutting,manufacture:renderManufacture,diagnostics:renderDiagnostics,ai:renderAI,field:renderField,sources:renderSources};
 if(hash.startsWith('lesson/'))renderLesson(hash.slice(7));else(actions[hash]||renderLearn)();
 updateProgress();window.scrollTo(0,0);window.dispatchEvent(new CustomEvent('academy:route',{detail:{route:hash}}));
 if(pendingLessonVoice){const mode=pendingLessonVoice;pendingLessonVoice=null;window.AcademyVoice?.start(mode)}
}
window.addEventListener('hashchange',route);

function renderLab(){
 disposeWorld();
 $('#main').innerHTML=heading('01 / SEE THE TOOL','Small geometry.<br>Big consequences.','Start here. Rotate a tool, open its cross-section, then explore the edge that turns workpiece material into a chip.','INTERACTIVE GEOMETRY')+`
 <div class="lab-grid"><div class="stage"><div class="stage-top"><div class="segmented" aria-label="Geometry views">${[['3d','3D tool'],['section','Cross-section'],['edge','Cutting edge']].map(([id,s])=>`<button data-view="${id}" class="${lab.view===id?'active':''}" aria-pressed="${lab.view===id}">${s}</button>`).join('')}</div><span class="model-tag">SCHEMATIC · NOT CAD</span></div><div id="model-stage" class="stage-canvas"></div><div class="stage-foot"><p id="model-caption"></p><div class="stage-controls"><button class="button small" id="spin">${lab.spin?'Pause':'Rotate'}</button><button class="button small" id="home-view">Reset view</button></div></div></div>
 <div class="panel control-panel"><span class="eyebrow">EXPLORE A TOOL FAMILY</span><div class="field"><label for="tool-kind">Tool family</label><select id="tool-kind"><option value="endmill" ${lab.kind==='endmill'?'selected':''}>Carbide end mill</option><option value="drill" ${lab.kind==='drill'?'selected':''}>PCB microdrill</option><option value="pcd" ${lab.kind==='pcd'?'selected':''}>PCD tipped form tool</option></select></div><div id="geometry-controls"></div><div class="insight" id="geometry-insight"></div></div></div>
 <div class="feature-row" id="features"></div><div class="lesson-strip"><p><span class="eyebrow">YOUR FIRST EXPERIMENT</span><span id="experiment-text"></span></p><a class="button primary" href="#learn">Start the learning path <span>→</span></a></div><p class="small-note" style="margin-top:16px">Geometry is deliberately simplified. Flute, edge and PCD construction details are not a manufacturable design. Chip flow, forces, wear and machine motion require separate models and validation.</p>`;
 $('#tool-kind').onchange=e=>{lab.kind=e.target.value;lab.exploded=false;lab.feature='edges';lab.flutes=lab.kind==='endmill'?3:2;lab.helix=lab.kind==='pcd'?0:30;renderLab()};
 $$('[data-view]').forEach(b=>b.onclick=()=>{lab.view=b.dataset.view;renderLab()});
 $('#spin').onclick=()=>{lab.spin=!lab.spin;$('#spin').textContent=lab.spin?'Pause':'Rotate'};
 $('#home-view').onclick=()=>{if(world){world.group.rotation.set(.18,0,-.3);world.camera.zoom=1;world.camera.updateProjectionMatrix()}else toast('This is a fixed teaching section. Use the angle controls to explore.')};
 const features=lab.kind==='pcd'?[['edges','PCD cutting layer','Diamond composite at the working edge.'],['flute','Carbide support','Support and pocket geometry carry cutting loads.'],['core','Tool body','The structural path to the holder.'],['shank','Brazed assembly','A joint connects a supported segment to the body.']]:[['edges','Cutting edge','The intersection that separates a chip.'],['flute','Flute / chip space','A route for chips to leave the cut.'],['core','Core / web','Material that supports the cutting edges.'],['shank','Shank','The part gripped by the tool holder.']];
 $('#features').innerHTML=features.map(([id,t,d],i)=>`<button class="feature-card ${lab.feature===id?'active':''}" data-feature="${id}" aria-pressed="${lab.feature===id}"><span>0${i+1}</span><strong>${t}</strong><p>${d}</p></button>`).join('');
 $$('[data-feature]').forEach(b=>b.onclick=()=>{lab.feature=b.dataset.feature;$$('[data-feature]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',c===b)});buildModel();updateLabText()});
 renderGeometryControls();if(lab.view==='3d')initWorld();else if(lab.view==='section')drawSection();else drawEdge();updateLabText();
}
function renderGeometryControls(){let h='';if(lab.view==='edge'){h=range('rake','Rake angle γ',-10,30,1,lab.rake,'°')+range('relief','Clearance angle α',3,18,1,lab.relief,'°')+'<p class="small-note">Idealized orthogonal section. These angles are not the helix angle and do not update the 3D flute.</p>'}else if(lab.kind==='pcd'){h='<div class="field"><span>Assembly view</span><button id="explode" class="button '+(lab.exploded?'active':'')+'">'+(lab.exploded?'Assemble segments':'Separate segments')+'</button><small>A generic two-tip assembly; CTC construction may differ. Shown larger than life.</small></div><p class="small-note">PCD is a cutting material. This example shows a PCD layer on a carbide-backed segment, joined to a body.</p>'}else{h=(lab.kind==='endmill'?range('flutes','Flute count z',2,6,1,lab.flutes):'<div class="field"><span>Two-flute drill</span><small>Point and cutting lips are schematic.</small></div>')+range('helix','Helix angle',0,50,1,lab.helix,'°')+range('core','Core / diameter',38,72,1,lab.core,'%')}
 $('#geometry-controls').innerHTML=h;for(const id of ['rake','relief','flutes','helix','core']){const e=$('#'+id);if(e)e.oninput=()=>{lab[id]=+e.value;$('#'+id+'-out').textContent=e.value+e.dataset.unit;if(lab.view==='3d')buildModel();if(lab.view==='section')drawSection();if(lab.view==='edge')drawEdge();updateLabText()}}const ex=$('#explode');if(ex)ex.onclick=()=>{lab.exploded=!lab.exploded;ex.textContent=lab.exploded?'Assemble segments':'Separate segments';ex.classList.toggle('active',lab.exploded);if(world)buildModel();else drawSection();updateLabText()};}
function updateLabText(){let title,body,experiment,caption;
 if(lab.view==='edge'){title=`Edge wedge β = ${90-lab.rake-lab.relief}°`;body='In this 2D section, rake + wedge + clearance = 90°. More positive rake or more clearance makes the supporting wedge thinner. Real tools need an edge radius or chamfer suited to the application.';experiment='Increase rake, then clearance. Watch the wedge lose supporting material even though both changes might look “sharper”.';caption='<strong>One idealized cutting edge</strong>Angles share the same orthogonal plane.'}
 else if(lab.kind==='pcd'){[title,body]={edges:['PCD is the working cutting layer','The dark surface represents a diamond composite bonded to its carbide backing during blank manufacture. Edge quality, grade and support matter as well as wear resistance.'],flute:['Carbide backs the PCD layer','The supported segment contains PCD bonded to carbide. The backing carries loads and provides a surface for joining the segment to the tool body.'],core:['The body carries the segment','The structural body transfers loads to the shank and holder. This generic model omits the detailed pockets, clearances and manufacturing allowances.'],shank:['Braze joins the backed segment to the body','The bronze layer represents the joint between the tool body and the carbide-backed PCD segment. It does not represent a braze joint between diamond and its carbide backing.']}[lab.feature];experiment='Separate the segments. Explain which material provides the cutting edge, which supports it, and what joins the assembly.';caption='<strong>PCD tipped form tool</strong>Dark: PCD · bronze: braze · grey: carbide'}
 else{const text={edges:['Edges do the cutting','An edge can look sharp in a drawing yet have a rounded or chipped microscopic profile. Edge preparation changes strength, minimum chip thickness and surface behavior.'],flute:['Chip space is a design constraint','More flutes place more edges around a fixed diameter. In this model, each flute gets narrower; real designs must also balance chip volume, core size and strength.'],core:['Support competes with chip space','Increase the core ratio and the flute becomes shallower. A larger core can improve support, but chip evacuation may become more difficult.'],shank:['The holder is part of the cutting system','The shank transfers torque and establishes location. Runout, grip, contamination and overhang can defeat an otherwise capable tool geometry.']};[title,body]=text[lab.feature];experiment=lab.kind==='drill'?'Raise the core ratio. The drill has more supporting material and less chip space. Why might deep PCB holes become harder to evacuate?':'Change three flutes to six, then increase the core ratio. Identify where the extra cutting edges and supporting material take space from.';caption=`<strong>${lab.kind==='drill'?'PCB microdrill':'Carbide end mill'} · ${lab.flutes} flutes · ${lab.helix}° helix</strong>${lab.view==='3d'?'Drag to orbit · Scroll to zoom · Arrow keys supported':'End-on section · Shaded center shows core'}`}
 $('#geometry-insight').innerHTML=`<strong>${title}</strong>${body}`;$('#experiment-text').textContent=experiment;$('#model-caption').innerHTML=caption;$('#spin').classList.toggle('hidden',lab.view!=='3d');$('#home-view').classList.toggle('hidden',lab.view!=='3d');
}
function disposeWorld(){if(!world)return;cancelAnimationFrame(world.raf);world.observer.disconnect();world.group.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){const ms=Array.isArray(o.material)?o.material:[o.material];ms.forEach(m=>m.dispose())}});world.renderer.dispose();world=null}
function initWorld(){disposeWorld();const host=$('#model-stage');try{const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputEncoding=THREE.sRGBEncoding;host.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','Interactive schematic cutting tool. Drag or use arrow keys to rotate; plus and minus to zoom.');renderer.domElement.setAttribute('role','img');renderer.domElement.tabIndex=0;const scene=new THREE.Scene();scene.add(new THREE.HemisphereLight(0xf6f9fc,0x464859,.9));for(const [x,y,z,intensity]of [[5,8,5,.75],[-6,1,3,.45],[1,-5,-5,.45]]){const l=new THREE.DirectionalLight(0xffffff,intensity);l.position.set(x,y,z);scene.add(l)}const camera=new THREE.OrthographicCamera(-6,6,7,-7,.1,100);camera.position.set(9,5,14);camera.lookAt(0,0,0);const group=new THREE.Group();group.rotation.set(.18,0,-.3);scene.add(group);world={renderer,scene,camera,group};
 const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);const a=w/h,extent=w<500?7.8:6.4;camera.left=-extent*a;camera.right=extent*a;camera.top=extent;camera.bottom=-extent;camera.updateProjectionMatrix()};world.observer=new ResizeObserver(resize);world.observer.observe(host);resize();buildModel();let drag=null;renderer.domElement.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)};renderer.domElement.onpointermove=e=>{if(!drag)return;group.rotation.y+=(e.clientX-drag.x)*.009;group.rotation.x+=(e.clientY-drag.y)*.009;drag={x:e.clientX,y:e.clientY}};renderer.domElement.onpointerup=()=>drag=null;renderer.domElement.onpointercancel=()=>drag=null;renderer.domElement.onwheel=e=>{e.preventDefault();camera.zoom=Math.min(2.6,Math.max(.65,camera.zoom*Math.exp(-e.deltaY*.001)));camera.updateProjectionMatrix()};renderer.domElement.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')group.rotation.y-=.18;if(e.key==='ArrowRight')group.rotation.y+=.18;if(e.key==='ArrowUp')group.rotation.x-=.18;if(e.key==='ArrowDown')group.rotation.x+=.18;if(e.key==='+'||e.key==='=')camera.zoom=Math.min(2.6,camera.zoom*1.1);if(e.key==='-')camera.zoom=Math.max(.65,camera.zoom/1.1);camera.updateProjectionMatrix()}};const tick=()=>{if(!world||world.renderer!==renderer)return;if(lab.spin)group.rotation.y+=.005;renderer.render(scene,camera);world.raf=requestAnimationFrame(tick)};tick();
 }catch(e){host.innerHTML='<div class="empty-state"><h3>3D rendering is unavailable in this browser.</h3><p>The cross-section and cutting-edge views still work.<br>Try opening this file in a browser with WebGL enabled.</p></div>'}}
function fluteRadius(t){t=((t%1)+1)%1;const c=lab.core/100;if(t<.1)return 1-.1*t/.1;if(t<.36)return .9-(.9-c)*(t-.1)/.26;if(t<.65)return c;return c+(1-c)*(t-.65)/.35}
function buildModel(){if(!world)return;const group=world.group;while(group.children.length){const o=group.children[0];o.traverse(x=>{x.geometry?.dispose();if(x.material)(Array.isArray(x.material)?x.material:[x.material]).forEach(m=>m.dispose())});group.remove(o)}
 const steel=new THREE.MeshStandardMaterial({color:lab.kind!=='pcd'&&lab.feature==='shank'?0x585c86:0xa9aab4,metalness:.65,roughness:.32});const shank=new THREE.Mesh(new THREE.CylinderGeometry(1,1,4.3,72),steel);shank.position.y=2.5;group.add(shank);const ring=new THREE.Mesh(new THREE.CylinderGeometry(1.015,1.015,.11,72),new THREE.MeshStandardMaterial({color:0x36395c,metalness:.4,roughness:.5}));ring.position.y=4.3;group.add(ring);
 if(lab.kind==='pcd'){const body=new THREE.Mesh(new THREE.CylinderGeometry(.75,.72,4.7,64),new THREE.MeshStandardMaterial({color:lab.feature==='core'?0x606599:0x858697,metalness:.5,roughness:.35}));body.position.y=-2;group.add(body);for(let j=0;j<2;j++){const a=j*Math.PI,assembly=new THREE.Group();const offset=lab.exploded?1.1:0;assembly.position.set(Math.cos(a)*(.69+offset),-2.7,Math.sin(a)*(.69+offset));assembly.rotation.y=-a;for(const [w,x,color]of [[.05,0,lab.feature==='shank'?0xf0b743:0xb8975a],[.28,.165,lab.feature==='flute'?0x454a7c:0x9798a4],[.115,.3625,lab.feature==='edges'?0x292c49:0x27293c]]){const piece=new THREE.Mesh(new THREE.BoxGeometry(w,2.2,.67),new THREE.MeshStandardMaterial({color,metalness:.3,roughness:.4}));piece.position.x=x;assembly.add(piece)}const edge=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(.42,-1.1,-.335),new THREE.Vector3(.42,1.1,-.335)]),new THREE.LineBasicMaterial({color:0xb9b9f9}));assembly.add(edge);group.add(assembly)}return}
 const seg=180,rings=95,pos=[],colors=[],indices=[],length=5.7,top=.35,bottom=top-length;const twist=Math.tan(lab.helix*Math.PI/180);for(let i=0;i<=rings;i++){const y=bottom+length*i/rings;const taper=lab.kind==='drill'?Math.min(1,(y-bottom)/1.1+.005):1;for(let j=0;j<=seg;j++){const a=j/seg*Math.PI*2;const t=j/seg*lab.flutes;const rr=fluteRadius(t)*taper;const theta=a+(y-top)*twist;pos.push(Math.cos(theta)*rr,y,Math.sin(theta)*rr);const c=new THREE.Color((t%1)<.1?0xb6b7c7:lab.feature==='flute'?0x64678e:0x717387);colors.push(c.r,c.g,c.b);if(i<rings&&j<seg){const p=i*(seg+1)+j;indices.push(p,p+seg+1,p+1,p+1,p+seg+1,p+seg+2)}}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,metalness:.5,roughness:.35,side:THREE.DoubleSide,transparent:lab.feature==='core',opacity:lab.feature==='core'?.27:1}));group.add(mesh);
 if(lab.kind==='endmill'){const shape=new THREE.Shape();for(let j=0;j<=seg;j++){const a=j/seg*Math.PI*2+(bottom-top)*twist,r=fluteRadius(j/seg*lab.flutes);if(j===0)shape.moveTo(Math.cos(a)*r,Math.sin(a)*r);else shape.lineTo(Math.cos(a)*r,Math.sin(a)*r)}const face=new THREE.Mesh(new THREE.ShapeGeometry(shape),new THREE.MeshStandardMaterial({color:0x6d708b,metalness:.45,roughness:.4,side:THREE.DoubleSide,transparent:lab.feature==='core',opacity:lab.feature==='core'?.2:1}));face.rotation.x=Math.PI/2;face.position.y=bottom;group.add(face)}
 const core=new THREE.Mesh((lab.kind==='drill'?new THREE.LatheGeometry([new THREE.Vector2(lab.core/100*.005,-length/2),new THREE.Vector2(lab.core/100,-length/2+1.0945),new THREE.Vector2(lab.core/100,length/2)],48):new THREE.CylinderGeometry(lab.core/100,lab.core/100,length,48)),new THREE.MeshStandardMaterial({color:lab.feature==='core'?0xb9b9f9:0x767892,metalness:.4,roughness:.45}));core.position.y=(top+bottom)/2;core.visible=lab.feature==='core';core.scale.set(.995,1,.995);group.add(core);
 for(let z=0;z<lab.flutes;z++){const points=[];for(let i=0;i<=100;i++){const y=bottom+length*i/100,theta=z/lab.flutes*Math.PI*2+(y-top)*twist,rr=(lab.kind==='drill'?Math.min(1,(y-bottom)/1.1+.005):1)*1.006;points.push(new THREE.Vector3(Math.cos(theta)*rr,y,Math.sin(theta)*rr))}group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:lab.feature==='edges'?0xb9b9f9:0x7d82b6})))}
}
function drawSection(){const host=$('#model-stage');if(lab.kind==='pcd'){host.innerHTML=`<svg class="edge-view" viewBox="0 0 600 520" role="img" aria-label="Schematic PCD segment cross section"><circle cx="300" cy="255" r="115" fill="#64748d" stroke="#273951" stroke-width="2"/>${[0,1].map(i=>{const x=i?185-(lab.exploded?42:0):415+(lab.exploded?42:0);return `<g transform="translate(${x},208) scale(${i?-1:1},1)"><rect width="7" height="94" fill="#bd9a5d"/><rect x="7" width="26" height="94" fill="#a8c3de"/><rect x="33" width="13" height="94" fill="#0d253d"/></g>`}).join('')}<text x="300" y="260" text-anchor="middle" fill="#0d253d" font-size="16">Tool body</text><text x="300" y="420" text-anchor="middle" fill="#273951" font-size="13">Supported PCD tips · joint shown schematically</text></svg>`;return}const pts=[];for(let j=0;j<=540;j++){const a=j/540*Math.PI*2,r=fluteRadius(j/540*lab.flutes)*143;pts.push(`${300+Math.cos(a)*r},${255+Math.sin(a)*r}`)}host.innerHTML=`<svg class="edge-view" viewBox="0 0 600 520" role="img" aria-label="Tool cross-section showing flutes, core and diameter"><circle cx="300" cy="255" r="143" fill="none" stroke="#a8c3de" stroke-dasharray="5 5"/><polygon points="${pts.join(' ')}" fill="#64748d" stroke="#273951" stroke-width="1.5"/><circle cx="300" cy="255" r="${143*lab.core/100}" fill="#a8c3de" fill-opacity=".78"/><line x1="157" y1="91" x2="443" y2="91" stroke="#273951"/><path d="M157 85v12M443 85v12" stroke="#273951"/><text x="300" y="80" font-size="13" text-anchor="middle" fill="#273951">Outer diameter D</text><text x="300" y="260" font-size="14" text-anchor="middle" fill="#0d253d">Core ${lab.core}% D</text>${Array.from({length:lab.flutes},(_,i)=>{const a=i/lab.flutes*2*Math.PI;return `<circle cx="${300+Math.cos(a)*143}" cy="${255+Math.sin(a)*143}" r="5" fill="#533afd"/>`}).join('')}<text x="300" y="430" font-size="13" text-anchor="middle" fill="#273951">${lab.flutes} cutting edges · ${lab.flutes} chip spaces</text></svg>`}
function drawEdge(){const rake=lab.rake*Math.PI/180,relief=lab.relief*Math.PI/180;const tx=340,ty=290;const ux=tx+155*Math.tan(rake),uy=ty-155;const fx=540,fy=ty-200*Math.tan(relief);$('#model-stage').innerHTML=`<svg class="edge-view" viewBox="0 0 650 520" role="img" aria-label="Orthogonal wedge schematic showing rake, clearance and wedge angles"><defs><marker id="edge-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#533afd"/></marker></defs><path d="M70 290H575V385H70Z" fill="#e3e8ee"/><path d="M70 259H${tx}V290H70Z" fill="#a8c3de"/><path d="M${tx} ${ty} L${ux} ${uy} L560 130 L${fx} ${fy}Z" fill="#64748d" stroke="#0d253d" stroke-width="2"/><line x1="${tx}" y1="${ty}" x2="${tx}" y2="105" stroke="#64748d" stroke-dasharray="4 4"/><line x1="${tx}" y1="${ty}" x2="580" y2="290" stroke="#64748d" stroke-dasharray="4 4"/><path d="M280 255Q${ux-28} 235 ${ux-25} 175Q${ux-25} 140 ${ux-70} 140" fill="none" stroke="#64748d" stroke-width="14"/><path d="M95 225H190" stroke="#533afd" stroke-width="2" marker-end="url(#edge-arrow)"/><text x="92" y="208" fill="#273951" font-size="12">Workpiece motion</text><text x="430" y="192" fill="#f6f9fc" font-size="14">Tool wedge</text><text x="435" y="214" fill="#f6f9fc" font-size="13">${90-lab.rake-lab.relief}°</text><text x="${Math.max(230,ux-20)}" y="107" fill="#273951" font-size="13">Rake γ = ${lab.rake}°</text><text x="405" y="320" fill="#273951" font-size="13">Clearance α = ${lab.relief}°</text><text x="110" y="353" fill="#273951" font-size="14">Workpiece</text><text x="200" y="157" fill="#273951" font-size="12">Chip</text><circle cx="${tx}" cy="${ty}" r="5" fill="#533afd"/><text x="300" y="425" fill="#273951" font-size="12" text-anchor="middle">Sharp corner idealization · edge radius omitted</text></svg>`}

