 return `<button class="module-card ${done?'is-complete':''} ${current?'is-current':''}" data-lesson="${m.id}" onclick="startLesson('${m.id}')"><span class="module-number">${done?'✓':String(i+1).padStart(2,'0')}</span><span class="module-copy"><h3>${escapeHTML(m.title)}</h3><p>${escapeHTML(m.subtitle)}</p></span><span class="module-meta"><span>${m.minutes} min</span><span class="module-state">${done?'Completed':current?'Up next':'Lesson + practice'}</span></span><span class="module-arrow" aria-hidden="true">→</span></button>`
