 $('#main').innerHTML=`<div class="lesson-topline"><a href="#learn" class="text-button">← Learning path</a><span class="lesson-position">Lesson ${i+1} of ${DATA.modules.length} <span aria-hidden="true">·</span> ${m.minutes} min</span></div>`+heading(m.group.toUpperCase(),escapeHTML(m.title),escapeHTML(m.subtitle))+`<div class="lesson-layout"><article class="lesson-body"><div class="learning-objectives" id="lesson-objectives"><span class="eyebrow">IN THIS LESSON</span><h3>You’ll learn to…</h3><ul>${m.objectives.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ul></div>${m.sections.map((s,j)=>`<section class="lesson-section" id="lesson-section-${j}"><div class="section-heading"><span class="section-number">${String(j+1).padStart(2,'0')}</span><h3 tabindex="-1">${escapeHTML(s.heading)}</h3></div><p>${escapeHTML(s.body)}</p>${s.bullets?`<ul>${s.bullets.map(b=>`<li>${escapeHTML(b)}</li>`).join('')}</ul>`:''}</section>`).join('')}<section class="lesson-section lesson-practice" id="lesson-practice"><span class="eyebrow">PUT IT INTO PRACTICE</span><h3 tabindex="-1">Try it on the shop floor</h3><p>${escapeHTML(m.exercise.prompt)}</p><details><summary>What a good answer includes</summary><p>${escapeHTML(m.exercise.answer)}</p></details></section><section class="lesson-section lesson-check" id="lesson-check"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3 tabindex="-1">${escapeHTML(m.quiz.question)}</h3><div class="quiz-options">${m.quiz.options.map((o,j)=>`<button data-answer="${j}"><span class="answer-letter" aria-hidden="true">${String.fromCharCode(65+j)}</span><span>${escapeHTML(o)}</span></button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback" aria-live="polite">${state.passed.includes(id)?'✓ Knowledge check previously passed.':''}</div></section><div class="lesson-actions"><button class="button primary" id="complete-lesson">${state.completed.includes(id)?'✓ Completed':'Complete lesson'}</button>${DATA.modules[i+1]?`<a class="button" href="#lesson/${DATA.modules[i+1].id}">Next lesson →</a>`:'<a class="button" href="#field">Take it to the floor →</a>'}</div><p class="small-note completion-hint">Pass the knowledge check to complete this lesson. Your progress is saved on this device.</p></article><aside class="lesson-aside"><div class="lesson-outline panel"><span class="eyebrow">YOUR LESSON AT A GLANCE</span><nav aria-label="In this lesson">${m.sections.map((s,j)=>`<button class="lesson-jump" data-jump="lesson-section-${j}"><span>${String(j+1).padStart(2,'0')}</span>${escapeHTML(s.heading)}</button>`).join('')}<button class="lesson-jump" data-jump="lesson-practice"><span>↗</span>Shop-floor practice</button><button class="lesson-jump" data-jump="lesson-check"><span>✓</span>Knowledge check</button></nav></div><div class="notes-panel panel"><div class="notes-heading"><h3>Your notes</h3><button class="button notes-dictate" data-voice-action="dictate"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/></svg>Dictate</button></div><textarea id="lesson-notes" aria-label="Notes for this lesson" placeholder="Capture an idea, observation, or question for your team…">${escapeHTML(state.notes[id]||'')}</textarea><p class="small-note">Saved on this device. Export your notes from the menu to keep a copy.</p></div><div class="source-panel panel"><span class="eyebrow">GO A LITTLE DEEPER</span><h3>Read the source</h3>${sourceLinks(m.sources)}${!m.sources.length?'<p class="small-note">Original learning framework and proposed operating practice.</p>':''}<a href="#lab" class="button">Explore in 3D ↗</a></div></aside></div>`;
